import requests
from pathlib import Path
tok=Path('.build/token.txt').read_text().strip()
kb=Path('.build/kb_id.txt').read_text().strip()
d=requests.get(f'http://127.0.0.1:8080/api/v1/knowledge-bases/{kb}',headers={'Authorization':f'Bearer {tok}'},timeout=60).json()['data']

def recover(s):
    # 每个 U+FFFD 对应原始 GBK 流中丢失的 1 个字节；存活字符的 UTF-8 编码即原始字节
    stream=[]
    for ch in s:
        if ch=='�': stream.append(None)
        else: stream.extend(ch.encode('utf-8'))
    out=[]; i=0
    while i < len(stream):
        b=stream[i]
        if b is None:
            # 与下一个字节合成一个丢失的 GBK 字
            nxt = stream[i+1] if i+1 < len(stream) else None
            out.append('？'); i += 2 if nxt is None else 1
            continue
        if b < 0x80:
            out.append(chr(b)); i+=1; continue
        if i+1 < len(stream) and stream[i+1] is not None:
            try: out.append(bytes([b,stream[i+1]]).decode('gbk'))
            except Exception: out.append('？')
            i+=2
        else:
            out.append('？'); i+=1
    return ''.join(out)

for f in ('name','description'):
    print(f'{f}: {recover(d.get(f) or \"\")}')
"

