        for k,v in obj.items(): hits+=scan(label,v,f'{path}.{k}')
    elif isinstance(obj,list):
        for i,v in enumerate(obj): hits+=scan(label,v,f'{path}[{i}]')
    elif isinstance(obj,str) and '�' in obj:
        hits.append((path,obj[:80]))
